import functools
from fastapi import FastAPI
from fastapi.testclient import TestClient
from fastapi.dependencies.utils import get_typed_signature

def deco(f):
    @functools.wraps(f)
    def wrapper(*a, **k):
        return f(*a, **k)
    return wrapper

def make():
    @deco
    def ep(item: "Item") -> "Item":
        return item
    return ep

class Item:
    pass

app = FastAPI()
app.get("/")(make())
print("ok", get_typed_signature(make()))
EOF
